--获取默认的合卡技
---@return integer
function QuestConfMgr:GetAutoMergeSkillId()
    --[[
    local mergeSkillId = 0
    local cfDatas = CfUtils.GetCfTable(AutoIds.IdSetting569)
    for k, v in pairs(cfDatas) do
        local vo = UnitSkillVo.New()
        vo:FillVo(v)
        if mergeSkillId == 0 then
            mergeSkillId = checkNumber(vo.skillId)
        elseif mergeSkillId > checkNumber(vo.skillId) then
            mergeSkillId = checkNumber(vo.skillId)
        end
    end
    ]]
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    return checkNumber(playerComponent.playerDojo.mergeSkill)
end

--光环技能表
function QuestConfMgr:GetMergeSkillTypeVo(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3085, "MergeSkillTypeVo", id)
    return vo
end

function QuestConfMgr:GetMergeSkillData(id)
    local vo = self:GetMergeSkillTypeVo(id)
    if not vo then
        return nil
    end

    local catT = CfUtils.Split(vo.catId)
    catT = checkTable(catT)

    local catEggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local t = checkTable(catEggComponent.cats)
    for k, v in pairs(t) do
        for _, id in pairs(catT) do
            if checkNumber(v.catId) == checkNumber(id) then
                return v
            end
        end
    end
    return nil
end

