--获取合卡技图片
function QuestConfMgr:GetMergeSkillImg(mergeSkillId)
    mergeSkillId = checkNumber(mergeSkillId)
    if mergeSkillId == 0 then
        mergeSkillId = self:GetAutoMergeSkillId()
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting569, "UnitSkillVo", mergeSkillId)
    if not vo then
        return nil
    end

    return vo.photoPath
end

---GetQuestTeamNum 获取该关卡的队伍数量
---@param questId number 关卡Id
function QuestConfMgr:GetQuestTeamNum(questId)
    if questId == Constants.SpecialQuestId.LadderStruggleId then
        return 3
    elseif questId == Constants.SpecialQuestId.ClubGVGId then
        return 3
    elseif questId == Constants.SpecialQuestId.LadderStruggleSingleId then
        return 1
    end

    local vo = self:GetQuestVoById(questId)
    if not vo then
        return 1
    end
    local nums = CfUtils.Split(vo.roleNun)
    if not nums then
        return 1
    end
    if table.count(nums) <= 0 then
        return 1
    end
    return table.count(nums)
end

---GetMaxTeamMemberNum 获取该关卡的上阵人数
---@param questId number 关卡Id
function QuestConfMgr:GetTeamMemberNum(questId, teamIndex)
    teamIndex = checkNumber(teamIndex)
    if teamIndex == 0 then
        teamIndex = 1
    end
    local vo = self:GetQuestVoById(questId)
    local count = 0
    if vo then
        local nums = CfUtils.Split(vo.roleNun)
        if nums then
            count = checkNumber(nums[teamIndex])
        end
    end

    if checkNumber(count) == 0 then
        local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
        count = teamComponent:GetMaxTeamMemberNum()
    end
    return count
end

