---GetQuestHelper 获取关卡锁定的机器人助手ID
---@param questId number 关卡Id
function QuestConfMgr:GetQuestHelpers(questId)
    local questVo
    local team = {}
    if not questId then
        return team
    end
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    questVo = self:GetQuestVoById(questId)
    if not questVo then
        return team
    end
    if checkNumber(questVo.petLineup) ~= 0 then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting721, "BattleHelperTeamVo", questVo.petLineup)
        if vo then
            local ids = CfUtils.Split(checkString(vo.lineupId))  --卡牌ID
            local poss = CfUtils.Split(checkString(vo.Station))  --队伍位置
            local relationLineupId = CfUtils.Split(checkString(vo.relationLineupId))  --队伍位置

            if #ids == #poss then
                for k, v in pairs(poss) do
                    team[checkNumber(v)] = CfUtils.GetTeamMemberData(Constants.TeamMemberType.QuestLockHelperCard, ids[k], nil, relationLineupId[k])
                end
            end
        end
    end

    return team, questVo
end

--是否解锁了委托
function QuestConfMgr:IsUnlockEntrust(questId)
    questId = checkNumber(questId)
    local questVo = self:GetQuestVoById(questId)
    if not questVo then
        return false
    end

    --是否未解锁
    local isUnLock = true
    local err = ""
    local appointment = checkNumber(questVo.appointment)
    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if appointment == Constants.EntrustBattleOpenCondition.Pass then
        isUnLock = self:IsPassQuest(questId)
        err = localize("通关当前关卡后解锁")
    elseif appointment == Constants.EntrustBattleOpenCondition.ThreeStarPass then
        isUnLock = self:IsPassAndCompleteAllCdtQuest(questId)
        err = localize("达成当前关卡三星条件后解锁")
    else
        isUnLock = false
        err = localize("不认识的解锁类型")
    end
    return isUnLock, err
end

--是否解锁了该关卡 par1参数
function QuestConfMgr:IsUnlockQuest(questId, par1)
    local questVo = self:GetQuestVoById(questId)
    if not questVo then
        return false
    end

    local unlockValues = questVo.unlockNum
    local t = CfUtils.Split(unlockValues)
    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if levelType == Constants.IDType.QuestCoinsCopy or--应策划要求，日常新增通关主线条件字段
            levelType == Constants.IDType.QuestExpCopy or
            levelType == Constants.IDType.QuestUpStarCopy or
            levelType == Constants.IDType.QuestDaily then
        table.insert(t, questVo.unlockRegion)
    elseif levelType == Constants.IDType.QuestRoleStoryCopy then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleStoryQuestComponent)
        return comp:IsUnlockQuestById(questId)
    elseif levelType == Constants.IDType.QuestRegion then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        return ActionUtils.IsUnlockRegionQuest(questId)
    elseif levelType == Constants.IDType.QuestAnnihilation then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        return ActionUtils.IsUnlockAnnihilationQuest(questId, par1)
    end
    if t then
        for k, v in pairs(t) do
            if not self:IsPassQuest(v) then
                return false
            end
        end
    end
    return true
end

