--是否任务可领取奖励
function QuestConfMgr:IsMainTaskCanDraw(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    local data = questComponent:GetCurTaskInfo()
    local isFinish = false
    if checkNumber(vo.task) > 0 then
        local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
        if checkNumber(taskVo.taskContentType) == Constants.TaskType.Submittals then
            isFinish = (GoodsUtils.GetThingNo(taskVo.taskContentId) >= checkNumber(taskVo.taskContenNum))
        else
            isFinish = (checkNumber(data.progress) >= checkNumber(taskVo.taskContenNum))
        end
    end
    return isFinish
end

--是否有任务
function QuestConfMgr:IsHaveTask(questId)
    local questVo = self:GetQuestVoById(questId)
    if not questVo then
        return false
    end

    return checkNumber(questVo.task) > 0
end

--获取当前op关卡id, 全部通过返回0
function QuestConfMgr:GetCurOpId()
    local questComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.QuestComponent)
    if isNull(questComp) then
        return 0
    end
    for i = 1,4 do
        if (not self:IsPassQuest(Constants.QUEST_OP_LEVEL[i])) then
            return Constants.QUEST_OP_LEVEL[i]
        end
    end
    return 0
end

--是否通关了该关卡
function QuestConfMgr:IsPassQuest(questId)
    questId = checkNumber(questId)
    --id是0算是通关
    if questId == 0 then
        return true
    end

    local questVo = self:GetQuestVoById(questId)
    if not questVo then
        return false
    end

    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if levelType == Constants.IDType.QuestMain then
        local questComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        if questComp:IsPassLevelById(questId) then
            return true
        end
    elseif levelType == Constants.IDType.QuestMainChallenge then
        local questComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        if questComp:IsPassChallengeLevelById(questId) then
            return true
        end
    elseif levelType == Constants.IDType.QuestPrologues then
        ---@type ProloguesQuestComponent
        local questComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ProloguesQuestComponent)
        if questComp:IsPassLevelById(questId) then
            return true
        end
    elseif levelType == Constants.IDType.QuestCoinsCopy or
            levelType == Constants.IDType.QuestExpCopy or
            levelType == Constants.IDType.QuestUpStarCopy or
            levelType == Constants.IDType.QuestDaily then
        local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
        if dailyQuestComponent:IsPassLevelById(questId) then
            return true
        end
    elseif levelType == Constants.IDType.QuestMediumPT then
        local MediumPTActivityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MediumPTActivityComponent)
        return MediumPTActivityComponent:IsPassLevelById(questId)
    elseif levelType == Constants.IDType.QuestAdvancedTraining then
        local AdvancedTrainingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.AdvancedTrainingComponent)
        return AdvancedTrainingComponent:IsPassLevelById(questId)
    elseif levelType == Constants.IDType.QuestPrimaryEquipCopy or
            levelType == Constants.IDType.QuestSeniorEquipCopy then
        local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
        return equipQuestComp:IsPassQuestById(questId)
    elseif levelType == Constants.IDType.QuestRoleStoryCopy then
        local roleStoryQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleStoryQuestComponent)
        return roleStoryQuestComp:IsPassQuestById(questId)
    elseif levelType == Constants.IDType.QuestTower then
        local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
        return towerQuestComponent:IsPassQuestById(questId)
    elseif levelType == Constants.IDType.QuestTalent then
        local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        return talentQuestComponent:IsPassQuestById(questId)
    elseif levelType == Constants.IDType.QuestBambooChanllenge then
        local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
        return BambooUtils.IsPassChallengeQuest(questId)
    elseif levelType == Constants.IDType.QuestNightCatTower then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatQuestComponent)
        return comp:IsPassLevelById(questId)
    elseif levelType == Constants.IDType.QuestNightCatPlot then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityNightCatComponent)
        return comp:IsPassLevelById(questId)
    elseif levelType == Constants.IDType.QuestHalloween then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
        return comp:IsPassLevelById(questId)
    elseif levelType == Constants.IDType.QuestHalloweenPlot then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
        return comp:IsPassPlotLevelById(questId)
    elseif levelType == Constants.IDType.QuestMapDecryptionTracking then
        local comp = MapDecryptionMgr:GetComponent()
        return comp:IsPassTrackLevelById(questId)
    elseif levelType == Constants.IDType.QuestRegion then   --区域
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        return ActionUtils.IsPassRegionQuest(questId)
    elseif levelType == Constants.IDType.QuestAnnihilation then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        return ActionUtils.IsPassAnnihilationQuest(questId)
    elseif levelType == Constants.IDType.QuestMapDecryptionMap then
        local comp = MapDecryptionMgr:GetComponent()
        return comp:IsPassMapLevelById(questId)
    elseif levelType == Constants.IDType.DreamAdventuresPlot then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DreamAdventuresComponent)
        return comp:IsPassPlotLevelById(questId)
    elseif levelType == Constants.IDType.JapaneseStoryPlot then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.JapaneseStoryComponent)
        return comp:IsPassPlotLevelById(questId)
    end
    return false
end

