--获取关卡类型
function QuestConfMgr:GetQuestType(questId)
    local vo = self:GetQuestVoById(questId)
    if not vo then
        return Constants.QuestBattleType.Battle
    end

    if checkNumber(vo.type) == Constants.QuestBattleType.Battle then
        return Constants.QuestBattleType.Battle
    elseif checkNumber(vo.type) == Constants.QuestBattleType.Story then
        return Constants.QuestBattleType.Story
    elseif checkNumber(vo.type) == Constants.QuestBattleType.All then
        return Constants.QuestBattleType.All
    end
    return Constants.QuestBattleType.Battle
end

