--主线重复刷得关卡 不消耗体力     暂时只有主线用
function QuestConfMgr:IsRepeatQuest(questId)
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    --主线
    if type == Constants.IDType.QuestMain then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local curQuestId = checkNumber(comp:GetCurQuestId())
        return curQuestId >= checkNumber(questId)
    elseif type == Constants.IDType.QuestMainChallenge then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        return self:IsPassQuest(questId)
    end

    return false
end

---GetCurChapterId 获取当前挑战的章节id
function QuestConfMgr:GetCurChapterId()
    local t = self:GetAllChapterVos()
    if not t then
        return 0, false
    end

    local id = 0
    for i = 1, #t do
        id = t[i].id
        if not self:IsPassChapter(t[i].id) then
            return id, false
        end
    end
    return id, true
end

