--是否有章节奖励可以领取
function QuestConfMgr:IsHasChapterRewardDraw()
    local t = self:GetAllChapterVos()
    if not t then
        return false
    end
    for k, v in pairs(t) do
        local _t = self:GetChapterStarInfo(v.id)
        for _k, _v in pairs(_t) do
            if self:IsCanDrawChapterReward(v.id, _v.ind) or QuestConfMgr:GetInstance():IsSideRedPointActive(v.id) then
                return true
            end
        end
    end
    return false
end

--章节是否可以领取奖励
function QuestConfMgr:IsCanChapterRewardDraw(chapterId)
    local _t = self:GetChapterStarInfo(chapterId)
    for _k, _v in pairs(_t) do
        if self:IsCanDrawChapterReward(chapterId, _v.ind) then
            return true
        end
    end
    return false
end

--是否领取了章节奖励
function QuestConfMgr:IsDrawChapterReward(chapterId, pos)
    ---@type QuestComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    return comp:IsDrawChapterReward(chapterId, pos)
end

--是否领取了章节奖励
function QuestConfMgr:IsCanDrawChapterReward(chapterId, pos)
    pos = checkNumber(pos)
    if pos <= 0 then
        return false
    end
    if self:IsDrawChapterReward(chapterId, pos) then
        return false, localize("该奖励已领取")
    end

    local t = self:GetChapterStarInfo(chapterId)
    local targetNum = t[pos].starNum
    local allNum, curNum = self:GetChapterStarGetNum(chapterId)
    return curNum >= checkNumber(targetNum)
end

--是否领取了全部的
function QuestConfMgr:IsDrawChapterAllReward(chapterId)
    local t = self:GetChapterStarInfo(chapterId)
    for k, v in pairs(t) do
        if not self:IsDrawChapterReward(chapterId, k) then
            return false
        end
    end
    return true
end

--获取星及信息
function QuestConfMgr:GetChapterStarInfo(chapterId)
    local vo = self:GetChapterVoByID(chapterId)
    if not vo then
        return {}
    end
    local _t = {}
    local t = checkTable(CfUtils.Split(vo.starNeed))
    for k, v in pairs(t) do
        local data =
        {
            ind = k,
            starNum = checkNumber(v),
            goodsId = checkString(vo["starRewardId"..k]),
            num = checkString(vo["starRewardNum"..k]),
        }
        table.insert(_t, data)
    end
    return _t
end

function QuestConfMgr:GetCurNeedChallengeQuestId(chapterId)
    local t = self:GetChallengeChapterIds(chapterId)
    if self:IsPassChallengeChapter(chapterId) then
        return t[#t]
    end

    for k, v in pairs(t) do
        if not self:IsPassQuest(v) then
            return v
        end
    end
    return t[1]
end

function QuestConfMgr:GetCurChapterNeedQuestId(chapterId)
    local t = self:GetChapterIds(chapterId)
    if self:IsPassChapter(chapterId) then
        return t[#t]
    end

    for k, v in pairs(t) do
        if not self:IsPassQuest(v) then
            return v
        end
    end
    return t[1]
end

function QuestConfMgr:GetNextQuestId(questId)
    local vo = self:GetQuestVoById(questId)
    if not vo then
        return questId
    end

    local t = {}
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if type == Constants.IDType.QuestMain or type == Constants.IDType.QuestPrologues then
        t = self:GetChapterIds(vo.chapter)
    elseif type == Constants.IDType.QuestMainChallenge then
        t = self:GetChallengeChapterIds(vo.chapter)
    end

    local isTrue = false
    for k, v in pairs(t) do
        if isTrue then
            return checkNumber(v)
        end
        if checkNumber(v) == checkNumber(questId) then
            isTrue = true
        end
    end
    return questId
end

---GetCurNeedQuestId 获取当前应该挑战的关卡id
function QuestConfMgr:GetCurNeedQuestId()
    local isAllPass = self:IsPassAllChapter()
    --全部通关
    if isAllPass then

    else
        local t = self:GetAllChapterVos()
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local questId = comp:GetCurQuestId()
        --第一个
        if checkNumber(questId) == 0 then
            local questIds = self:GetChapterIds(t[1].id)
            if questIds then
                return questIds[1]
            end
        end
        local vo = self:GetQuestVoById(questId)
        if not vo then
            return 0
        end
        local curChapter = checkNumber(vo.chapter)
        local isPassChapter = self:IsPassChapter(curChapter)
        if isPassChapter then
            t = self:GetChapterIds(curChapter + 1)
            return t[1]
        else
            local questIds = self:GetChapterIds(vo.chapter)
            for k, v in pairs(questIds) do
                if not self:IsPassQuest(v) then
                    return v
                end
            end
        end
    end

    return 0
end

