function QuestConfMgr:GetAllChapterStarGetNum()
    local t = self:GetAllChapterVos()
    if not t then
        return 0, 0
    end

    local num1, num2 = 0, 0
    for i = 1, #t do
        if self:IsUnlockChallengeChapter(t[i].id) then
            local allNum, curNum = self:GetChapterStarGetNum(t[i].id)
            num1 = num1 + allNum
            num2 = num2 + curNum

        end
