--后去章节获得的星星数量
function QuestConfMgr:GetChapterStarGetNum(chapterId)
    local t = self:GetChallengeChapterIds(chapterId)
    if not t then
        return 0, 0
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)

    local getNum = 0
    local allNum = table.count(t) * 3
    for k, v in pairs(t) do
        local data = comp:GetQuestStarInfo(v)
        if data then
            for k, v in pairs(data) do
                if checkNumber(v) == 1 then
                    getNum = getNum + 1
                end
            end
        end
    end
    return allNum, getNum
end

---GetPassQuestNumByChapterId 获取一章的通关关卡数
---@param chapterId number 章节Id
function QuestConfMgr:GetPassQuestNumByChapterId(chapterId)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting280, chapterId)
    if not t then
        return 0, 0
    elseif self:IsPassChapter(chapterId) then
        return 0, #t
    end

    local num = 0
    for k, v in pairs(t) do
        if self:IsPassQuest(v) then
            num = num + 1
        end
    end
    return num, #t
end

