--是否解锁了章节
function QuestConfMgr:IsUnlockChapter(chapterId,isChallenge)
    if not chapterId then
        return false, ""
    end
    chapterId = checkString(chapterId)
    local vo = isChallenge and self:GetHardChapterVoByID(chapterId) or self:GetChapterVoByID(chapterId)
    if not vo then
        return false, ""
    end
    local err = ""
    local isUnlock = true
    if not self:IsPassQuest(vo.unlockNum) then
        isUnlock = false
        err = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, checkString(vo.unlockNum))
    elseif not GameUtils.IsUnlocked(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level)) then
        isUnlock = false
        err = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level))
    elseif not GameUtils.IsUnlocked(Constants.CommonUnlockType.TeamLevel, checkString(vo.teamLevel)) then
        isUnlock = false
        err = localize("小队评级达到_num_解锁", { _num_ = CfUtils.GetTeamLevelSignByNum(vo.teamLevel)})
    end
    return isUnlock, err
end

function QuestConfMgr:IsPasskMainChapter(chapterId, isChallenge)
    if isChallenge then
        return self:IsPassChallengeChapter(chapterId)
    else
        return self:IsPassChapter(chapterId)
    end
end

