--------------------------------------------------------------------关卡条件--------------------------------------------------------------
--判断关卡条件是否达成
function QuestConfMgr:CheckConditionReach(condition, data)
    if not condition or not data then
        return false
    end
    condition = checkTable(condition)
    data = checkTable(data)
    if condition.type == Constants.QuestCondition.BattlePass then
    elseif condition.type == Constants.QuestCondition.DeadMemberLimit then
    elseif condition.type == Constants.QuestCondition.RoundLimit then
    elseif condition.type == Constants.QuestCondition.AllCardUltimatelyHp then
    elseif condition.type == Constants.QuestCondition.RoundDamage then
    elseif condition.type == Constants.QuestCondition.AttackDamage then
    elseif condition.type == Constants.QuestCondition.AttrCardDamage then
    elseif condition.type == Constants.QuestCondition.CardCount then
    elseif condition.type == Constants.QuestCondition.BossAcquiredState then
    elseif condition.type == Constants.QuestCondition.CardAcquiredState then
    elseif condition.type == Constants.QuestCondition.TotalFightValue then

    elseif condition.type == Constants.QuestCondition.TeamRare or condition.type == Constants.QuestCondition.TeamCharacterType or
            condition.type == Constants.QuestCondition.TeamCareer or condition.type == Constants.QuestCondition.TeamAttribute or
            condition.type == Constants.QuestCondition.TeamStar or condition.type == Constants.QuestCondition.CardRole or
            condition.type == Constants.QuestCondition.CardQuailty or condition.type == Constants.QuestCondition.CardJob or
            condition.type == Constants.QuestCondition.ContainsAttrCardPass then
        return self:_CheckCardCondition(condition, data)
    --战中条件判断
    elseif condition.type >= Constants.QuestCondition.UseQualitySkill and condition.type >= Constants.QuestCondition.KillBossRoundNum then
        self:_CheckBattingCondition(condition, data)
    end

    return false
end

---_CheckBattingCondition 判断战中和卡技之类的条件
---conditionData table 条件数据
---cardsData table 卡牌数组 ！！必须是table
function QuestConfMgr:_CheckBattingCondition(conditionData, data)
    conditionData = checkTable(conditionData)
    local type = checkNumber(conditionData.type)
    data = checkTable(data)

    if type == Constants.QuestCondition.UseQualitySkill then
    elseif type == Constants.QuestCondition.UseTypeSkill then
    elseif type == Constants.QuestCondition.UseSkillMergeSkillNum then
    elseif type == Constants.QuestCondition.MoveSkillMergeSkillNum then

    elseif type == Constants.QuestCondition.GetMergeSkill then

    elseif type == Constants.QuestCondition.MergeStarSkillNum then

    elseif type == Constants.QuestCondition.GetTargetMergeSkill then

    elseif type == Constants.QuestCondition.RoleSpMax then

    elseif type == Constants.QuestCondition.GetRestainSkill then
    elseif type == Constants.QuestCondition.EndBattleRoundNum then
    elseif type == Constants.QuestCondition.KillBossWeakPointRoundNum then
    elseif type == Constants.QuestCondition.KillBossRoundNum then
    end
end

---_CheckCardCondition 判断卡牌相关的条件
---conditionData table 条件数据
---cardsData table 卡牌数组 ！！必须是table
function QuestConfMgr:_CheckCardCondition(conditionData, cardsData)
    conditionData = checkTable(conditionData)
    local type = checkNumber(conditionData.type)
    cardsData = checkTable(cardsData)

    local count = 0
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    --卡牌属性
    if type == Constants.QuestCondition.ContainsAttrCardPass then
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.attributeType) == checkNumber(conditionData.otherParam) then
                        count = count + 1
                    end
                end
            end
        end
        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
            return count >= checkNumber(conditionData.value)
        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
            return count <= checkNumber(conditionData.value)
        end
    elseif type == Constants.QuestCondition.CardJob then
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.career) == checkNumber(conditionData.otherParam) then
                        count = count + 1
                    end
                end
            end
        end

        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
            return count >= checkNumber(conditionData.value)
        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
            return count <= checkNumber(conditionData.value)
        end
    elseif type == Constants.QuestCondition.CardQuailty then
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.rare) == checkNumber(conditionData.otherParam) then
                        count = count + 1
                    end
                end
            end
        end

        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
            return count >= checkNumber(conditionData.value)
        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
            return count <= checkNumber(conditionData.value)
        end
    elseif type == Constants.QuestCondition.CardRole then
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.characterId) == checkNumber(conditionData.otherParam) then
                        count = count + 1
                    end
                end
            end
        end

        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
            return count >= checkNumber(conditionData.value)
        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
            return count <= checkNumber(conditionData.value)
        end
    elseif type == Constants.QuestCondition.TeamStar then
        if table.count(cardsData) < 1 then
            return false
        end
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                if checkNumber(cardDojo.star) < checkNumber(conditionData.otherParam) then
                    return false
                end
            end
        end
    elseif type == Constants.QuestCondition.TeamCareer then
        if table.count(cardsData) < 1 then
            return false
        end
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.career) ~= checkNumber(conditionData.otherParam) then
                        return false
                    end
                end
            end
        end
    elseif type == Constants.QuestCondition.TeamAttribute then
        if table.count(cardsData) < 1 then
            return false
        end
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.attributeType) ~= checkNumber(conditionData.otherParam) then
                        return false
                    end
                end
            end
        end
    elseif type == Constants.QuestCondition.TeamCharacterType then
        if table.count(cardsData) < 1 then
            return false
        end
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.characterId) ~= checkNumber(conditionData.otherParam) then
                        return false
                    end
                end
            end
        end
    elseif type == Constants.QuestCondition.TeamRare then
        if table.count(cardsData) < 1 then
            return false
        end
        for k, v in pairs(cardsData) do
            local cardDojo = cardComp:GetCardById(v)
            if cardDojo then
                local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
                if cardVo then
                    if checkNumber(cardVo.rare) < checkNumber(conditionData.otherParam) then
                        return false
                    end
                end
            end
        end
    end

    --默认为true
    return true
end

---IsCardDataSufficeCondition 判断卡牌相关的条件
---conditionData table 条件数据
---cardData table 卡牌数据
function QuestConfMgr:IsCardDataSufficeCondition(conditionData, cardData, cardsData)
    conditionData = checkTable(conditionData)
    local type = checkNumber(conditionData.type)
    cardData = checkTable(cardData)

    local isCardSuffice = false
    local isTeamSuffice = false

    local count = 0
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    --卡牌属性
    if type == Constants.QuestCondition.ContainsAttrCardPass then
        local cardDojo = cardComp:GetCardById(cardData.id)
        if cardDojo then
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
            if cardVo then
                if checkNumber(cardVo.attributeType) == checkNumber(conditionData.otherParam) then
                    isCardSuffice = true
                end
            end
