---IsCompleteAllCondition 是否完成关卡的所有条件
---questId string 条件参数
function QuestConfMgr:IsCompleteAllCondition(questId)
    local t = self:GetQuestConditions(questId)
    --没有条件就是完成
    if not t then
        return true
    end

    for k, v in pairs(t) do
        if not self:IsCompleteCondition(questId, k) then
            return false
        end
    end
    return true
end

---IsCompleteCondition 是否完成关卡的某个条件
---questId string 条件参数
---id string 条件id  传了是判断单个条件  不传判断这个关卡所有的条件
---@param trailCondition table 可为空
function QuestConfMgr:IsCompleteCondition(questId, id, trailCondition)
    questId = checkNumber(questId)
    id = checkNumber(id)

    local cdt = self:GetQuestConditions(questId, id, trailCondition)
    if not cdt then
        return false
    end

    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if type == Constants.IDType.QuestCoinsCopy or
            type == Constants.IDType.QuestExpCopy or
            type == Constants.IDType.QuestUpStarCopy or
            type == Constants.IDType.QuestDaily then
                return false
        --local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
        --if dailyQuestComponent:IsCompleteCondition(questId, cdt.id) then
        --    return true
        --end
        --试炼的关卡限制条件
    elseif type == Constants.IDType.QuestTrail then
        ---@type TeamComponent
        local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
        local t = teamComponent:GetTeamByQuestId(questId)
        local tmp = {}
        if t then
            for k, v in pairs(t) do
                table.insert(tmp, v.refId)
            end
            return self:CheckConditionReach(cdt, tmp)
        end
    elseif type == Constants.IDType.QuestPrimaryEquipCopy then
        local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
        if equipQuestComp:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type == Constants.IDType.QuestMain or type == Constants.IDType.QuestMainChallenge then
        local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        if questComponent:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type == Constants.IDType.QuestMediumPT then
        local MediumPTActivityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MediumPTActivityComponent)
        if MediumPTActivityComponent:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type == Constants.IDType.QuestBambooChanllenge then
        local BambooQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BambooQuestComponent)
        if BambooQuestComponent:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type == Constants.IDType.QuestHalloween then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
        if comp:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type == Constants.IDType.QuestMapDecryptionTracking then
        ---@type MapDecryptionComponent
        local comp = MapDecryptionMgr:GetComponent()
        if comp:IsCompleteCondition(questId, cdt.id) then
            return true
        end
    elseif type ~= Constants.IDType.None then
        return true
    end
    return false
end

---GetQuestConditions 如果有条件id返回该条件id数据，否则获取所有条件
---id string 条件id
---questId string 关卡id
---@param trailCondition table 限制条件
function QuestConfMgr:GetQuestConditions(questId, conditionId, trailCondition, conditionIdName, conditionValueName)
    local t = {}
    local arrayT = {}   --全量的时候额外返回一个数组的
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    local cdtIds, values

    if type == Constants.IDType.QuestTrail and trailCondition then
        cdtIds = {}
        values = {}
        for _, v in pairs(trailCondition) do
            table.insert(cdtIds, checkNumber(v.id))
            table.insert(values, checkNumber(v.num))
        end
    elseif conditionIdName and conditionValueName then
        cdtIds, values = self:GetQuestConditionField(questId, conditionIdName, conditionValueName)
    else
        cdtIds, values = self:GetQuestConditionIds(questId)
    end
    if not cdtIds then
        return t, arrayT
    end
    cdtIds = checkTable(cdtIds)
    values = checkTable(values)

    for i = 1, #cdtIds do
        local id = cdtIds[i]
        if checkNumber(id) ~= 0 then
            local data = self:GetQuestCondition(cdtIds[i], values[i])
            xTry(function()
                self:HandleStarConditionsDesc(data, questId, i)
            end)
            if checkNumber(conditionId) == 0 then
                t[checkString(id)] = data
                table.insert(arrayT, data)
            elseif checkNumber(conditionId) == checkNumber(id) then
                return data
            end
        end
    end
    return t, arrayT
end

function QuestConfMgr:HandleStarConditionsDesc(data, questId, index)
    local type = checkNumber(data.type)
    if type < 1000 or type > 2999 then return end
    local vo = self:GetQuestVoById(questId)
    local starConditionNum = vo["starConditionNum"] or vo["conditionValue"]
    local listStarConditionNum = CfUtils.Split(starConditionNum)
    local starConditionRound = vo["starConditionRound"]
    local listStarConditionRound = checkTable(CfUtils.Split(starConditionRound))
    local questTypeVo = CfUtils.GetCfVo(AutoIds.IdSetting820, "QuestConditionVo", checkString(data.id))
    local desc = checkString(questTypeVo.condition)
    local SIGN = {
        --目标次数
        sign_1 = "_target_num_",
        --目标百分比
        sign_2 = "_target_num2_",
        --目标回合
        sign_3 = "_time_", }
    desc = string.fmt(desc, { _target_num_ = checkString(checkInt(listStarConditionNum[index])),
                            _target_num2_ = checkString(checkInt(checkNumber(listStarConditionNum[index] * 100))),
                            _time_ = checkString(checkInt(listStarConditionRound[index]))})
    data.desc = desc
end

---GetQuestCondition 获取一个条件
---@param id string 条件id
---@param value string 条件参数
---@param arg table 外部影响参数   服务器额外传参
function QuestConfMgr:GetQuestCondition(id, value, arg)
    id = checkString(id)
    value = checkString(value)
    local valueTabs = CfUtils.Split(value, ",")
    if table.count(valueTabs) > 1 then
        return self:GetQuestConditionWithMoreCf(id, value, arg)
    end
    --只会走这一个
    value = checkString(valueTabs[1])

    local t = CfUtils.GetConditionData()
    t.id = id
    t.value = value
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting820, "QuestConditionVo", id)
    if not vo then
        return t
    end

    t.type = checkNumber(vo.type)
    t.arg = arg
    t.otherParam = checkNumber(vo.otherParam)
    t.comparType = checkNumber(vo.comparisonOperators)
    t.desc = self:GetQuestConditionDesc(vo.condition, t.type, value, t.comparType, arg)

    return t
end


---GetQuestConditionWithMoreCf 获取一个多配置的条件  不修改原始额外加的方法  如果表配置参数大于1走这里
---@param id string 条件id
---@param value string 条件参数
---@param arg table 外部影响参数   服务器额外传参
function QuestConfMgr:GetQuestConditionWithMoreCf(id, value, arg)
    id = checkString(id)
    value = checkString(value)

    local t = CfUtils.GetConditionData()
    t.id = id
    t.value = value
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting820, "QuestConditionVo", id)
    if not vo then
        return t
    end
    t.type = checkNumber(vo.type)
    t.arg = arg
    t.otherParam = checkNumber(vo.otherParam)
    t.comparType = checkNumber(vo.comparisonOperators)
    t.desc = self:GetQuestConditionDesc(vo.condition, t.type, value, t.comparType, arg)
    return t
end

---GetQuestConditionDesc 获取一个条件的描述
---desc string
---value string 条件参数
---comparType string 比较类型
---comparType string 比较类型
---arg table 外部影响参数
function QuestConfMgr:GetQuestConditionDesc(desc, type, value, comparType, arg)
    desc = checkString(desc)
    type = checkNumber(type)
    value = checkString(value)
    comparType = checkNumber(comparType)

    local comparStr = ""
    if comparType == Constants.QuestConditionComparType.GreaterThan then
        comparStr = localize("大于等于")
    elseif comparType == Constants.QuestConditionComparType.LessThan then
        comparStr = localize("小于等于")
    end

    local stateStr = ""
    --状态类型单独处理
    if type == Constants.QuestCondition.BossAcquiredState then

    elseif type == Constants.QuestCondition.CardAcquiredState then

    end

    local valueTabs = CfUtils.Split(value, ",")
    --如果表是多个配置参数
    if valueTabs and table.count(valueTabs) > 1 then
        local t = {}
        for i = 1, table.count(valueTabs) do
            local key = "_num"..i.."_"
            t[key] = self:GetConditionVlaue(type, valueTabs[i])
        end
        desc = string.fmt(desc, t)
    else
        desc = string.fmt(desc, { _target_num_ = self:GetConditionVlaue(type, value), _target_compar_ = comparStr, _target_type_ = stateStr })
    end

    --desc = localize(desc, { _target_num_ = value, _target_compar_ = comparStr, _target_type_ = stateStr })




    return checkString(desc)
end

function QuestConfMgr:GetConditionVlaue(type, value)
    type = checkNumber(type)
    value = checkNumber(value)
    if type == Constants.QuestCondition.AllCardUltimatelyHp or type == Constants.QuestCondition.FriendlyCallHpNum then
        value = value * 100
    end
    return value
end

--获取关卡所有条件id和参数(通过传参获取 字段，没有返回空)
function QuestConfMgr:GetQuestConditionField(questId, conditionIdName, conditionValueName)
    local vo = self:GetQuestVoById(questId)
    if not vo then return {}, {} end
    local cdtId = vo[conditionIdName]
    if (not cdtId) or cdtId == 0  then return {}, {} end
    local value = vo[conditionValueName] ~= nil and vo[conditionValueName] or ""
    local cdtIds = CfUtils.Split(cdtId)
    local values = CfUtils.Split(value)
    return checkTable(cdtIds), checkTable(values)
end


--获取关卡所有条件id和参数
function QuestConfMgr:GetQuestConditionIds(questId)
    local vo = self:GetQuestVoById(questId)
    if not vo then
        return {}, {}
    end

    local cdtId = vo.conditionId or vo.starCondition
    if not cdtId == 0 then
        return {}, {}
    end
    local value = vo.conditionValue or vo.starConditionNum
    value = value ~= nil and value or ""

    local cdtIds = CfUtils.Split(cdtId)
    local values = CfUtils.Split(value)
    return checkTable(cdtIds), checkTable(values)
end

