---GetDailyQuestIdsByType 获取某个类型副本的所有关卡
---@param type number 类型
function QuestConfMgr:GetDailyQuestIdsByType(type)
    local tableFile = settingMgr:Get(string.format("%sIDGroup", AutoIds.IdSetting312))
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(type)
    local ids = checkTable(parse_strings(row:Get("id"), ','))
    table.sort(ids, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)

    return checkTable(ids)
end

