---IsUnLockSeniorEquipCopy 是否解锁了高级装备副本类型
---@param Id string
function QuestConfMgr:IsUnLockSeniorEquipCopyType(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting847, "QuestSeniorEquipTypeVo", checkString(id))
    if not vo then
        return false
    end
    local quests = CfUtils.Split(vo.unlockNum)
    --如果没配为开启
    if not quests then
        return true
    end
    --数组为0 也为开启
    if table.count(quests) <= 0 then
        return true
    end

    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
    for k, v in pairs(quests) do
        if equipQuestComp:IsPassLevelById(v) then
            return true
        end
    end

    return false
end

---GetSeniorEquipBossVo 获取高级装备副本boss的vo
function QuestConfMgr:GetSeniorEquipBossVo(questId)
    if checkNumber(questId) == 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", questId)
    if not vo then
        return nil
    end
    local levels = CfUtils.Split(vo.pointID)
    if not levels then
        return
    end
    for k, v in pairs(levels) do
        local levelVo = self:GetQuestVoById(v)
        if levelVo then
            if checkNumber(levelVo.pointType) == Constants.RoleClass.Boss then
                return levelVo
            end
        end
    end
    return nil
end

