---IsUnlockChapterById 是否解锁章节
---@param chapterId string 章节id
function QuestConfMgr:IsUnlockChapterById(chapterId)
    if checkNumber(chapterId) == 0 then
        return true
    end
    local vo = self:GetRoleStoryChapterVo(chapterId)
    if vo then
        return GameUtils.IsUnlocked(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId)), GameUtils.GetUnlockDescr(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    end
    return false
end

--所有的结局数量
function QuestConfMgr:GetRoleStoryOverFinaleIdNum(roleId)
    local t = self:GetRoleStoryChapterIds(roleId)
    if not t then
        return 0, 0
    end
    local allNum = 0
    local hasNum = 0
    for k, v in pairs(t) do
        local _t = self:GetRoleStoryOverFinaleCgIds(v)
        if _t then
            for _, _v in pairs(_t) do
                allNum = allNum + 1
                if self:IsHasOverFinaleId(_v) then
                    hasNum = hasNum + 1
                end
            end
        end
    end
    return allNum, hasNum
end

--章节的结局数量
function QuestConfMgr:GetRoleStoryChapterOverFinaleIdNum(chapterId)
    local t = self:GetRoleStoryOverFinaleCgIds(chapterId)

    local allNum = 0
    local hasNum = 0
    if not t then
        return allNum, hasNum
    end

    for k, v in pairs(t) do
        allNum = allNum + 1
        if self:IsHasOverFinaleId(v) then
            hasNum = hasNum + 1
        end
    end
    return allNum, hasNum
end

--是否可以领取
function QuestConfMgr:IsCanDrawRoleQuestRewardById(rewardId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleStoryQuestComponent)
    local isDraw = comp:IsDrawRewardId(rewardId)
    if isDraw then
        return false
    end

    local vo = self:GetQuestRoleStoryRewardVo(rewardId)
    if not vo then
        return false
    end

    local allNum, hasNum = self:GetRoleStoryChapterOverFinaleIdNum(vo.stageID)
    return (checkNumber(hasNum) >= checkNumber(vo.finaleNum))
end

--角色是否有可领取的奖励
function QuestConfMgr:IsRoleHasDrawRewardId(roleId)
    local t = self:GetRoleStoryRewardIdsByRoleId(roleId)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if self:IsCanDrawRoleQuestRewardById(v) then
            return true
        end
    end
    return false
end

--章节是否有可领取的奖励
function QuestConfMgr:IsHasDrawRewardId(chapterId)
    local t = self:GetRoleStoryRewardIdsByChapterId(chapterId)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if self:IsCanDrawRoleQuestRewardById(v) then
            return true
        end
    end
    return false
end

--是否所有的领取了
function QuestConfMgr:IsAllDrawRewardId(chapterId)
    local t = self:GetRoleStoryRewardIdsByChapterId(chapterId)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if not self:IsDrawRoleQuestRewardById(v) then
            return false
        end
    end
    return true
end

