function QuestConfMgr:GetMonsterHeadIcon(questVo, isSmall)
    if not questVo then
        return nil
    end
    isSmall = checkBool(isSmall)
    local t = self:GetEnemysDataInfo(questVo.id)
    if not t or #t <= 0 then
        return nil
    end
    local data = checkTable(t[math.ceil(#t / 2)])

    local vo = CardConfMgr:GetBaseMonstVo(data.id)
    if vo then
        local skinVo = CardConfMgr:GetCardSkinBySkinId(vo.skinId)
        if skinVo then
            if isSmall then
                ---小头像
                return skinVo.buffHead
            else
                return skinVo.cardDrawing
            end
        end
    end
    return nil
end

--获取一关的boss数据
function QuestConfMgr:GetMonsterData(questId)
    if not questId then
        return nil
    end
    local t = self:GetEnemysDataInfo(questId)
    if not t or #t <= 0 then
        return nil
    end
    local data = checkTable(t[math.ceil(#t / 2)])
    if checkNumber(data.id) == 0 then
        return nil
    end
    local monstVo = CardConfMgr:GetInstance():GetBaseMonstVo(data.id)

    return monstVo
end

