---IsUnlockTeamByIndex 是否解鎖了编队
---@param teamIndex integer 编队下标
function QuestConfMgr:IsUnlockTeamByIndex(teamIndex, levelType)
    teamIndex = checkNumber(teamIndex)

    local isUnlock = true
    local errMsg = ""
    if levelType == Constants.IDType.QuestArena then
        return isUnlock, errMsg
    end
    if teamIndex == 2 then
        local vo = self:GetWorldBossParamVo(8)
        if vo then
            isUnlock = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PlayerLevel, checkString(vo.num))
            errMsg  = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PlayerLevel, checkString(vo.num))
        else
            isUnlock = false
        end
    elseif teamIndex == 3 then
        local vo = self:GetWorldBossParamVo(9)
        if vo then
            isUnlock = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PlayerLevel, checkString(vo.num))
            errMsg  = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PlayerLevel, checkString(vo.num))
        else
            isUnlock = false
        end
    end
    return isUnlock, errMsg
end

