---GetWorldBossBossId 获取世界bossid
---@param worldBossPlanId string boss排期id
function QuestConfMgr:GetWorldBossBossVo(worldBossPlanId)
    if not worldBossPlanId then
        return nil
    end

    local BossPlanVo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(worldBossPlanId)
    if not BossPlanVo then
        return nil
    end

    local lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(BossPlanVo.range)
    if lineUpInfo then
        lineUpInfo = checkTable(lineUpInfo)
        --只有一波怪
        lineUpInfo = checkTable(lineUpInfo[1])
        local t = lineUpInfo.wave1NpcId
        if t then
            t = checkTable(t)
            for i = 1, #t do
                local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(t[i])
                if vo then
                    --boss
                    if checkNumber(vo.monsterClass) == Constants.RoleClass.Elite then
                        return vo
                    end
                end
            end
        end
    end
    return nil
end

---GetWorldBossUpData 获取世界boss提升的数据
---@param upCardGroupId string 提升组id
function QuestConfMgr:GetWorldBossUpData(upCardGroupId)
    local t, _t = {}, {}
    if not upCardGroupId then
        return t, _t
    end
    local allId = CfUtils.GetIdGroupData(AutoIds.IdSetting974, upCardGroupId)
    if not allId then
        return t, _t
    end

    for k, v in pairs(allId) do
        local vo = self:GetWorldBossUpCardVo(v)
        if vo then
            vo.cardId = vo.upParam
            table.insert(t, vo)
        end
    end
    return t
end

local WorldBossRankReward
--获取奖励by排名
function QuestConfMgr:GetRankRewardByRankNum(rankNum)
    rankNum = checkNumber(rankNum)

    if not WorldBossRankReward then
        WorldBossRankReward = {}
        local t = CfUtils.GetCfTable(AutoIds.IdSetting978)
        if t then
            local WorldBossRankRewardVo = import("Game.Setting.Vo.WorldBossRankRewardVo")
            for k, v in pairs(t) do
                local vo = WorldBossRankRewardVo.New()
                vo:FillVo(v)
                table.insert(WorldBossRankReward, vo)
            end
        end
    end
    if not WorldBossRankReward then
        return {}
    end

    for k, v in pairs(WorldBossRankReward) do
        if checkNumber(v.upperLimit) <= rankNum and checkNumber(v.lowerLimit) >= rankNum then
            local t = {}
            local rewardT = CfUtils.Split(v.reward)
            local rewardNumT = CfUtils.Split(v.rewardNum)
            for k, v in pairs(rewardT) do
                table.insert(t, {
                    goodsId = rewardT[k],
                    num = rewardNumT[k],
                })
            end
            return t
        end
    end
    return {}
end

--获取编队界面标题名字
function QuestConfMgr:GetTitleName(type)
    if type == Constants.IDType.QuestMain then     --迷宫
        return localize("主线剧情")
    elseif type == Constants.IDType.QuestMaze then     --迷宫
        return localize("竞技试炼")
    elseif type == Constants.IDType.QuestGachaCoin                        --抽卡普通
      or type == Constants.IDType.QuestGachaCoinChallenge then     --抽卡挑战
        return localize("竞技试炼")
    elseif type == Constants.IDType.QuestTower then   --高级装备副本
        return localize("竞技试炼")
    elseif type == Constants.IDType.QuestTrail then   --试炼
        return localize("竞技试炼")
    elseif type == Constants.IDType.QuestSeniorEquipCopy then   --高级装备副本
        return localize("竞技试炼")
    else
        return localize("竞技试炼")
    end
    return ""
end

