function QuestConfMgr:GetDataBuffDesc(vo)
    local str = ""
    if not vo then
        return str
    end
    local ids = CfUtils.Split(vo.upBuff)
    if not ids then
        return str
    end
    for k, v in pairs(ids) do
        local vo = self:GetQuestUpBuffVo(v)
        if vo then
            str = str..vo.desc
        end
    end
    return str
end

---IsCardUp 卡牌是否是up角色
---@param cardId number 卡牌id
---@param upBuffData table 增益数据
function QuestConfMgr:IsCardUp(cardId, upBuffData)
    cardId = checkNumber(cardId)
    if cardId == 0 or not upBuffData then
        return false
    end
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if not cardVo then
        return false
    end

    --for upType, datas in pairs(upBuffData) do
    --    for k, upBuffVo in pairs(datas) do
    --        if upType == Constants.UpRoleBuffType.CardId then
    --            if checkNumber(cardId) == checkNumber(upBuffVo.upParam) then
    --                return true, upBuffVo
    --            end
    --        elseif upType == Constants.UpRoleBuffType.Career then
    --            if checkNumber(cardVo.career) == checkNumber(upBuffVo.upParam) then
    --                return true, upBuffVo
    --            end
    --        elseif upType == Constants.UpRoleBuffType.Attribute then
    --            if checkNumber(cardVo.attributeType) == checkNumber(upBuffVo.upParam) then
    --                return true, upBuffVo
    --            end
    --        elseif upType == Constants.UpRoleBuffType.CharacterType then
    --            if checkNumber(cardVo.characterId) == checkNumber(upBuffVo.upParam) then
    --                return true, upBuffVo
    --            end
    --        elseif upType == Constants.UpRoleBuffType.Rare then
    --            if checkNumber(cardVo.rare) == checkNumber(upBuffVo.upParam) then
    --                return true, upBuffVo
    --            end
    --        end
    --    end
    --end

    for i, v in ipairs(upBuffData) do
        local type = checkInt(v.type)
        if type == Constants.UpRoleBuffType.CardId then
            if checkNumber(cardId) == checkNumber(v.refId) then
                return true, v
            end
        elseif type == Constants.UpRoleBuffType.Career then
            if checkNumber(cardVo.career) == checkNumber(v.refId) then
                return true, v
            end
        elseif type == Constants.UpRoleBuffType.Attribute then
            if checkNumber(cardVo.attributeType) == checkNumber(v.refId) then
                return true, v
            end
        elseif type == Constants.UpRoleBuffType.CharacterType then
            if checkNumber(cardVo.characterId) == checkNumber(v.refId) then
                return true, v
            end
        elseif type == Constants.UpRoleBuffType.Rare then
            if checkNumber(cardVo.rare) == checkNumber(v.refId) then
                return true, v
            end
        end
    end
    --end

    return false
end

