function QuestConfMgr:GetTalentQuestIdsByCopyId(copyId)
    copyId = checkNumber(copyId)
    if copyId <= 0 then
        return {}
    end

    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting1825, copyId)
    return t
end

---GetTalentCopyIdByPlanIdAndDifficulty 难度获取副本id
---@param planId string 排期id
---@param difficulty string 难度
function QuestConfMgr:GetTalentCopyIdByPlanIdAndDifficulty(planId, difficulty)
    planId = checkNumber(planId)
    difficulty = checkNumber(difficulty)

    local t = self:GetTalentCopyIdsByPlanId(planId)
    if not t then
        return 0
    end
    if planId <= 0 or difficulty <= 0 then
        return t[1]
    end

    local copyId = 0
    for k, v in pairs(t) do
        local vo = self:GetTalentCopyVo(v)
        if vo then
            if checkNumber(vo.regionLevel) <= difficulty then
                copyId = v
            end
        end
    end
    return copyId
end

---GetTalentRewardOutPutByQuestId 获取副本打到该关卡时的奖励产出
---@param copyId string 副本id
---@param questId string 关卡id
function QuestConfMgr:GetTalentRewardOutPutByQuestId(copyId, questId, isFinal)
    if checkNumber(copyId) <= 0 or checkNumber(questId) <= 0 then
        return 0
    end
    local copyVo = self:GetTalentCopyVo(copyId)
    if not copyVo then
        return 0
    end
    local t = self:GetTalentQuestIdsByCopyId(copyId)
    if not t then
        return 0
    end

    local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
    local num = checkNumber(copyVo.baseReward)
    if talentQuestComponent:GetIsActive() then
        num = CfUtils.Ceil(num * self:GetTalentRewardMagnification())
    end

    local propNum = self:GetTalentNotPassRewardProp()
    for k, v in pairs(t) do
        local buffId = talentQuestComponent:GetBuffIdByQuestId(v)
        local vo = self:GetTalentBuffVo(buffId)
        if vo then
            num = CfUtils.Ceil(num * checkNumber(vo.rewardRatio))
        end

        if checkNumber(v) == checkNumber(questId) then
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(v)
            if isPass then
                return CfUtils.Ceil(num)
            else
                if isFinal then
                    return CfUtils.Ceil(num * propNum)    --最终领奖 没通关要
                else
                    return CfUtils.Ceil(num)
                end
            end
        end
    end
    return CfUtils.Ceil(num)
end

---GetTalentBaseRewardNum 获取副本基础奖励
---@param copyId string 副本id
function QuestConfMgr:GetTalentBaseRewardNum(copyId)
    local copyVo = self:GetTalentCopyVo(copyId)
    if not copyVo then
        return 0
    end

    local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
    local num = checkNumber(copyVo.baseReward)
    if talentQuestComponent:GetIsActive() then
        num = num * self:GetTalentRewardMagnification()
    end
    return CfUtils.Ceil(num)
end

---GetTalentCurChallengeQuestId 获取副本当前应该挑战的关卡id
function QuestConfMgr:GetTalentCurChallengeQuestId()
    local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
    local copyId = talentQuestComponent:GetCurCopyId()
    if checkNumber(copyId) <= 0 then
        return nil
    end

    local t = self:GetTalentQuestIdsByCopyId(copyId)
    if not t then
        return nil
    end
    local questId = talentQuestComponent:GetCurQuestId()
    if checkNumber(questId) <= 0 then
        return t[1]
    end
    local ind = checkNumber(table.keyof(t, checkString(questId)))
    if ind >= table.count(t) then
        return t[ind]
    end
    return t[ind + 1]
end

