---GetAllUpData 获取所有的up数据
---@param groupIds number 组id
function QuestConfMgr:GetAllUpDataByVos(vos)
    if not vos then
        return nil
    end

    local _t = {}
    for k, v in pairs(vos) do
        if not _t[checkNumber(v.upType)] then
            _t[checkNumber(v.upType)] = {}
        end
        table.insert(_t[checkNumber(v.upType)], v)
    end

    return _t
end

---GetUpBuffDataByStr 获取通用up数据 分割符的方式
---@param planId table 包含字段的data upParam/upBuff/upType
function QuestConfMgr:GetUpBuffDataByStr(data)
    if not data then
        return nil
    end
    local t1 = CfUtils.Split(data.upType)
    local t2 = CfUtils.Split(data.upParam)
    local t3 = CfUtils.Split(data.upBuff)
    local t = {}
    local num = math.min(math.min(#t1, #t2), #t3)
    for i = 1, num do
        if not t[checkNumber(t1[i])] then
            t[checkNumber(t1[i])] = {}
        end
        table.insert(t[checkNumber(t1[i])], {
            upType = t1[i],
            upParam = t2[i],
            upBuff = t3[i],
        })
    end
    return t
end

---GetUpBuffDescr upbuff 全量名字
---@param data table upbuffdata upParam/upBuff/upType
function QuestConfMgr:GetUpBuffDescr(data)
    if not data then
        return ""
    end
    local name, path = self:GetBuffNameAndImagePath(data)
    local vo = self:GetQuestUpBuffVo(data.upBuff)
    if vo then
        name = name..vo.desc
    end
    return name
end

---GetBuffNameAndImagePath buff名字和图片
---@param data table upbuffdata upParam/upBuff/upType
function QuestConfMgr:GetBuffNameAndImagePath(data)
    if not data then
        return "", ""
    end

    local param = checkNumber(data.upParam)
    local upType = checkNumber(data.upType)
    if upType == Constants.UpRoleBuffType.CardId then
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(param)
        if cardVo then
            return checkString(cardVo.name), CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(param)
        end
    elseif upType == Constants.UpRoleBuffType.Career then
        local vo = CardConfMgr:GetInstance():GetCardCareerRowByType(param)
        if vo then
            return checkString(vo.name)..localize("情绪武装"), CardConfMgr:GetInstance():GetCardCareerIconByType(param)
        end
    elseif upType == Constants.UpRoleBuffType.Attribute then
        local row = CfUtils.GetCfLine(AutoIds.IdSetting116, param)
        local name = CS.ParseUtils.ParseLocalizeText(row, "name")
        return checkString(name)..localize("情绪武装"), CardUtils.GetGoodsCardAttrIconByCardAttrType(param)
    elseif upType == Constants.UpRoleBuffType.CharacterType then
        local vo = CardConfMgr:GetInstance():GetRolesByCharacterType(param)
        if vo then
            return checkString(vo.catName)..localize("情绪武装"), CardConfMgr:GetInstance():GetCharacterTypeImagePath(param)
        end
    elseif upType == Constants.UpRoleBuffType.Rare then
        local path, name = CfUtils.GetRareBgRare(param, checkNumber(param))
        return checkString(name)..localize("品质情绪武装"), path
    end
    return "", ""
end

