--解锁的缓存
local UnlockCookie = {}
function QuestConfMgr:CheckUnlockInfo(type, id)
    local systemToggleIds = SystemToggleMgr:GetInstance():GetSystemToggleIds(type, id)
    if systemToggleIds then
        for k, v in pairs(systemToggleIds) do
            UnlockCookie[checkString(v)] = 1
        end
    end
end

--判断有咩有缓存
function QuestConfMgr:IsHasUnlockCookie(systemId)
    if checkNumber(systemId) <= 0 then
        return false
    end
    local num = checkNumber(UnlockCookie[checkString(systemId)])
    UnlockCookie[checkString(systemId)] = nil
    return (num == 1)
end

