--是否解锁了支线类型
function QuestConfMgr:IsUnlockSideType(id)
    local vo = self:GetQuestSideTypeVo(id)
    local questVo = self:GetQuestVoById(vo.unlockNum)
    return self:IsPassQuest(vo.unlockNum), localize("_name_解锁", {_name_ = questVo.label or questVo.name})
end

--是否解锁了支线关卡
function QuestConfMgr:IsUnlockSideQuest(id)
    local vo = self:GetQuestSideVo(id)
    if not vo then
        return false, ""
    end

    local isUnlock, err = self:IsUnlockSideType(vo.group)
    if not isUnlock then
        return false, err
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    local curId = comp:GetSideInfoById(vo.group)
    --return checkNumber(curId) >= checkNumber(vo.unlock), localize("_name_解锁", {_name_ = vo.la})
    return checkNumber(curId) >= checkNumber(vo.unlock), localize("完成上一篇章")
end

--是否通关了支线关卡
function QuestConfMgr:IsPassSideQuest(id)
    local vo = self:GetQuestSideVo(id)
    if not vo then
        return false
    end

    local isUnlock, err = self:IsUnlockSideType(vo.group)
    if not isUnlock then
        return false
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    local curId = comp:GetSideInfoById(vo.group)
    return checkNumber(curId) >= checkNumber(id)
end

--支线红点是否亮
function QuestConfMgr:IsSideRedPointActive(chapterId)
    local t = self:GetAllSideTypes(chapterId)
    for k, v in pairs(t) do
        local t1 = self:GetAllSideIds(v)
        for _, id in pairs(t1) do
            local isUnlock = self:IsUnlockSideQuest(id)
            local isPass = self:IsPassSideQuest(id)
            if isUnlock and not isPass then
                return true
            end
        end
    end
    return false
end

