function QuestConfMgr:IsTeamContentCondition(t, type, id, armId, attributeId)
    for k, v in pairs(t) do
        if not isNull(v.cardId) then
            local b1 = self:CheckCardCondition(type, id, v.cardId)
            local b2 = self:CheckCardArmCondition(type, armId, v.cardId)
            local b3 = self:CheckCardAttrCondition(type, attributeId, v.cardId)

            if b1 or b2 or b3 then
                return true
            end
        end
    end
    return false
end

--队伍是否可以去战斗
function QuestConfMgr:IsTeamCanSet(t, questId)
    t = checkTable(t)
    local vo = self:GetQuestVoById(questId)
    if not vo then
        return true
    end

    vo = self:GetQuestTeamLimitVo(vo.roleRestrictions)
    if not vo then
        return true
    end

    for i = 1, 4 do
        local type = checkNumber(vo["type"..i])
        local id = vo["roleId"..i]
        local arm = vo["arm"..i]
        local attrId = vo["attribute" .. i]

        local b = self:IsTeamContentCondition(t, type, id, arm, attrId)
        if checkNumber(type) == Constants.TeamLimitType.Must then
            if not b then
                return false
            end
        elseif checkNumber(type) == Constants.TeamLimitType.Limit then
            if b then
                return false
            end
        end
    end
    return true
end

--判断这张卡是否符合条件
function QuestConfMgr:CheckCardTeamLimitType(questId, type, cardId)
    if checkNumber(questId) <= 0 or checkNumber(cardId) <= 0 or checkNumber(type) <= 0 then
        return false
    end

    local vo = self:GetQuestVoById(questId)
    if not vo then
        return false
    end

    return self:CheckCardByTeamLimitId(vo.roleRestrictions, type, cardId)
end

function QuestConfMgr:CheckCardByTeamLimitId(limitId, targetType, cardId)
    limitId = checkNumber(limitId)
    if limitId <= 0 then
        return false
    end

    local vo = self:GetQuestTeamLimitVo(limitId)
    if not vo then
        return false
    end

    for i = 1, 4 do
        local type = vo["type"..i]
        local id = vo["roleId"..i]
        local armId = vo["arm"..i]
        local attrId = vo["attribute" .. i]
        local raceId = vo["raceId"..i]
        --检测目标类型
        if checkNumber(type) == checkNumber(targetType) then
            if checkInt(id) > 0 then
                if self:CheckCardCondition(type, id, cardId) then
                    return true
                end
            elseif checkInt(armId) > 0 then
                if self:CheckCardArmCondition(type, armId, cardId) then
                    return true
                end
            elseif checkInt(attrId) > 0 then
                if self:CheckCardAttrCondition(type, attrId, cardId) then
                    return true
                end
            elseif attrId then
                if self:CheckCardRaceCondition(type,raceId,cardId) then
                    return true
                end
            end
        end
    end
    return false
end

function QuestConfMgr:CheckCardCondition(type, id, cardId)
    type = checkNumber(type)
    id = checkNumber(id)

    if type == 0 then
        return true
    end
    local vo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if not vo then
        return false
    end
    --必须上阵
    if checkNumber(type) == Constants.TeamLimitType.Must then
        return (checkNumber(id) == checkNumber(vo.characterId))
    --无法上阵
    elseif checkNumber(type) == Constants.TeamLimitType.Limit then
        return (checkNumber(id) == checkNumber(vo.characterId))
    end

    return false
end

function QuestConfMgr:CheckCardArmCondition(type, targetId, cardId)
    type = checkNumber(type)
    targetId = checkNumber(targetId)

    if type == 0 then
        return true
    end

    if targetId == 0 then
        return false
    end
    --必须上阵
    if checkNumber(type) == Constants.TeamLimitType.Must then
        return (checkNumber(targetId) == checkNumber(cardId))
        --无法上阵
    elseif checkNumber(type) == Constants.TeamLimitType.Limit then
        return (checkNumber(targetId) == checkNumber(cardId))
    end

    return false
end

function QuestConfMgr:CheckCardAttrCondition(type, targetId, cardId)
    type = checkNumber(type)
    targetId = checkNumber(targetId)

    if type == 0 then
        return true
    end

    if targetId == 0 then
        return false
    end

    local vo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if not vo then
        return false
    end

    if checkNumber(type) == Constants.TeamLimitType.Must then
        return (checkNumber(vo.attributeType) == checkNumber(targetId))
    elseif checkNumber(type) == Constants.TeamLimitType.Limit then
        return (checkNumber(vo.attributeType) == checkNumber(targetId))
    end

    return false
end

function QuestConfMgr:CheckCardRaceCondition(type, raceId, cardId)
    type = checkNumber(type)
    raceId = checkNumber(raceId)

    if type == 0 then
        return true
    end

    if raceId == 0 then
        return false
    end

    local vo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if not vo then
        return false
    end

    if checkNumber(type) == Constants.TeamLimitType.Must then
        return (checkNumber(vo.race) == checkNumber(raceId))
    elseif checkNumber(type) == Constants.TeamLimitType.Limit then
        return (checkNumber(vo.race) == checkNumber(raceId))
    end

    return false
end

