function QuestConfMgr:IsShowCatBall(questId, questType)
    local HideCatQuestType = {
        [Constants.IDType.QuestAnnihilation]                = true,
        [Constants.IDType.QuestLadderStruggle]              = true,
        [Constants.IDType.QuestClubGVG]                     = true,
        [Constants.IDType.QuestCardExperience]              = true,
        [Constants.IDType.ActivityQuestSkinExperience]              = true,
        [Constants.IDType.QuestPatrolMaze]                  = true,
        [Constants.IDType.QuestConstractFoodAnnihilation]   = true,
    }

    local HideCatQuesId = {
        [Constants.SpecialQuestId.LadderId]                 = true,
        [Constants.SpecialQuestId.LadderStruggleId]         = true,
        [Constants.SpecialQuestId.LadderStruggleSingleId]   = true,
        [Constants.SpecialQuestId.ClubGVGId]                = true,
        [Constants.SpecialQuestId.FriendPVPId]              = true,
    }
    if questType == nil then
        questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    end
    local isShowCatBall = not (HideCatQuesId[questId] == true or HideCatQuestType[questType] == true)
    isShowCatBall = isShowCatBall and GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007)
    return isShowCatBall
end

function QuestConfMgr:IsHideFetters(questId, questType)
    local HideFettersType = {
        [Constants.IDType.QuestPatrolMaze] = true,
        [Constants.IDType.QuestClubGVG] = true,
    }
    if questType == nil then
        questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    end
    local isHideFetters = HideFettersType[checkInt(questType)] == true
    return isHideFetters
end

--- 获取主线章节BGM
function QuestConfMgr:GetCurrentMainChapterBGM()
    local questComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    local questId = questComp:GetCurQuestId()
    local vo = self:GetMainQuestPlotVo(questId)
    return isNull(vo) and "" or vo.bgm
end

--- 指定的主线关卡是否是首通
---@param questId any
function QuestConfMgr:IsMainChapterFirstPass(questId)
    local questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if questType == Constants.IDType.QuestMain then
        local questComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        if not questComp:IsPassLevelById(questId) then
            return true
        else
            return false
        end
    end
    return false
end

return QuestConfMgr
